/** A semantic colour token key, e.g. `text-primary`. */
export type SemanticColorToken = keyof typeof semanticColors;

/** A supported colour mode. */
export type ColorMode = 'light' | 'dark';

/** The CSS custom property a semantic colour is emitted as, e.g. `--color-semantic-text-primary`. */
export const semanticColorsVar = (token: SemanticColorToken) => semanticColorsSource[token].cssVar;
